/* ATLAS_REVIEW_UI */
/* Source-backed additions to the existing catalog; no synthetic product imagery. */
(() => {
'use strict';
const data=window.TOY_ATLAS;if(!data?.products?.length)return;
const byId=new Map(data.products.map(p=>[p.id,p]));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=v=>{try{const u=new URL(v,location.href);return /^https?:$/.test(u.protocol)?u.href:'#'}catch{return '#'}};
const a=(u,label)=>`<a href="${esc(safe(u))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const num=n=>Number(n||0).toLocaleString('en-US');
const short=(v,n=130)=>String(v||'').length>n?String(v).slice(0,n-1)+'…':String(v||'');
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const active=t=>t?.source&&t.observed&&(!t.expires_on||t.expires_on>=today);
const currency=(v,c)=>v==null?'Not provided':new Intl.NumberFormat('en-US',{style:'currency',currency:/^[A-Z]{3}$/.test(c)?c:'USD'}).format(v);
const style=document.createElement('style');style.textContent=`
.review-bar{margin:14px 0 22px;padding:15px 18px;border:1px solid #d8e4de;border-radius:10px;background:#f8fbf9;font-size:13px;line-height:1.65}.review-bar strong{color:#123d35}.review-bar summary{cursor:pointer;font-weight:650;font-size:14px}.review-small{font-size:12px;color:#55675e;line-height:1.65}.review-table-wrap{overflow:auto;max-height:510px;margin-top:12px}.review-table{border-collapse:collapse;width:100%;min-width:650px;background:white;font-size:12px}.review-table th,.review-table td{padding:10px 12px;text-align:left;border-bottom:1px solid #e2e9e5}.review-table th{position:sticky;top:0;background:#e9f2ed;color:#123d35;z-index:1}.review-table td:first-child{font-weight:650}.review-table .missing-brand{color:#8b491b}.review-group{margin-top:22px;font-weight:700}.review-reason{margin:12px 0 0;padding:12px;background:#edf4ef;border-radius:7px;font-size:12px;line-height:1.6;color:#294436}.review-reason strong{display:block;font-size:12px;margin-bottom:5px}.review-reason p{margin:0 0 6px}.review-reason small{display:block;color:#53675c;font-size:11px}.review-reason a,.review-details a,.review-bar a{color:#1b634e;text-decoration:underline;text-underline-offset:3px}.review-spec{font-size:12px;line-height:1.55;margin:12px 0 0;padding-top:10px;border-top:1px solid #e2e9e5;color:#435a4c}.review-spec b{color:#253d30}.review-image-note{font-size:11px;line-height:1.5;color:#6b756e;margin-top:6px}.review-details{margin:22px 0;padding-top:18px;border-top:1px solid #d9e3dc}.review-details h3{font-size:18px;margin:0 0 12px}.review-details dl{display:grid;grid-template-columns:minmax(90px,.45fr) minmax(0,1fr);gap:10px 16px;font-size:13px;line-height:1.6}.review-details dt{font-weight:650}.review-details dd{margin:0;overflow-wrap:anywhere}.review-photos{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:12px}.review-photo{border:1px solid #dce6df;padding:3px;background:white;border-radius:7px;overflow:hidden;cursor:pointer;min-width:0}.review-photo img{width:100%;height:95px;object-fit:contain}.review-options{margin-top:15px}.review-options summary{font-weight:650;cursor:pointer}.review-options table{width:100%;border-collapse:collapse;font-size:12px}.review-options td,.review-options th{padding:9px 7px;text-align:left;border-bottom:1px solid #e3e8e4;overflow-wrap:anywhere}.review-options th{background:#eef4ef}.review-context{margin-top:14px;padding:13px;background:#fff7e9;border-radius:7px;line-height:1.65;font-size:12px}.review-checklist-status{display:inline-block;background:#edf3ef;color:#345544;border-radius:4px;padding:3px 6px;font-size:10px}.review-source-leads{font-size:12px;line-height:1.7;margin-top:16px}.review-source-leads li{margin:8px 0}.review-feature-list{padding-left:18px;font-size:13px;line-height:1.7}.review-bar button{font:inherit;color:#1b634e;background:transparent;border:0;padding:0;cursor:pointer;text-align:left;text-decoration:underline}.review-not-audit{font-size:12px;line-height:1.6;color:#685b3c}.review-reason button{font:inherit;color:#1b634e;background:none;border:0;padding:0;cursor:pointer;text-decoration:underline}@media(max-width:760px){.review-bar{padding:13px}.review-details dl{grid-template-columns:85px minmax(0,1fr);gap:8px}.review-photos{grid-template-columns:repeat(3,minmax(0,1fr))}.review-photo img{height:80px}.review-reason{font-size:12px}.review-table{min-width:590px}}
`;document.head.append(style);

function brandPanel(){
 if(!data.brand_checklist?.length||document.getElementById('brandCoverageReview'))return;
 const box=document.createElement('details');box.id='brandCoverageReview';box.className='review-bar';
 const captured=data.brand_checklist.filter(b=>b.records).length;
 const groups=[...new Set(data.brand_checklist.map(b=>b.group))];
 box.innerHTML=`<summary>Brand coverage & item checks <span class="review-small">— ${captured} of ${data.brand_checklist.length} priority names have products</span></summary><p class="review-small">Details review: <strong>${esc(data.detail_reviewed||'Not recorded')}</strong>. ${num(data.stats.with_specifications)} entries have material or size information. ${num(data.stats.source_linked_images)} photos were matched to the exact source listing. This is <b>not</b> a visual audit of every variant or complete China-market coverage.</p>${groups.map(g=>`<div class="review-group">${esc(g)}</div><p class="review-small">${esc(data.brand_checklist.find(b=>b.group===g).basis)} ${a(data.brand_checklist.find(b=>b.group===g).source,'Selection source')}</p><div class="review-table-wrap"><table class="review-table"><thead><tr><th>Brand / maker</th><th>Products / series</th><th>With specs</th><th>Release dates</th><th>China launch prices</th><th>Coverage</th></tr></thead><tbody>${data.brand_checklist.filter(b=>b.group===g).map(b=>`<tr><td>${b.records?`<button data-review-brand="${esc(b.brand)}">${esc(b.brand)}</button>`:esc(b.brand)}</td><td>${num(b.records)}</td><td>${num(b.with_details)}</td><td>${num(b.with_release)}</td><td>${num(b.with_china_price)}</td><td class="${b.records?'':'missing-brand'}">${b.records?'Partial':'Missing'}</td></tr>`).join('')}</tbody></table></div>`).join('')}<p class="review-not-audit">“Partial” means some listings are included, not every current series or China seller. Blank sales fields mean the source did not disclose units. A brand-level growth story does not prove that all its products are trending.</p>${data.source_leads?.length?`<details class="review-source-leads"><summary>${num(data.source_leads.length)} non-item / mixed-product pages kept separately</summary><p>Shopping services, bags and mixed collections are excluded from the toy and trending counts. They remain source leads for further research.</p><ul>${data.source_leads.map(p=>`<li>${a(p.listings?.[0]?.url,p.name)}<br>${esc(p.exclusion_reason)}</li>`).join('')}</ul></details>`:''}`;
 document.getElementById('stats')?.after(box);
}
function enhanceCards(){
 for(const el of document.querySelectorAll('.product-card[data-product-id]')){
  if(el.dataset.reviewDone)continue;el.dataset.reviewDone='true';
  const p=byId.get(el.dataset.productId);if(!p)continue;
  const body=el.querySelector('.card-body'),d=p.details||{};if(!body)continue;
  const spec=document.createElement('div');spec.className='review-spec';
  const parts=[];if(d.size)parts.push('<b>Size:</b> '+esc(short(d.size,100)));if(d.material||p.material)parts.push('<b>Material:</b> '+esc(short(d.material||p.material,110)));if(p.regular_designs)parts.push('<b>Designs:</b> '+esc(p.regular_designs)+' regular'+(p.secret_designs?' + '+esc(p.secret_designs)+' secret':''));
  spec.innerHTML=parts.slice(0,2).join('<br>');if(parts.length)body.append(spec);
  const t=p.trend;if(active(t)){
   const weak=/retailer/i.test(t.label||'');const reason=document.createElement('section');reason.className='review-reason';
   reason.innerHTML=`<strong>${weak?'Why this shop highlights it':'Why it’s flagged as trending'}</strong><p>${esc(short(t.summary,245))}</p><small>${esc(t.market||'Market not specified')} · ${esc(t.observed)}<br>${esc(t.level||'Source-reported signal')}</small>${a(t.source,'Read the evidence')}${weak?'<small>Retailer selection only—not measured China-wide growth.</small>':''}`;body.append(reason);
  }
  if(p.image_review){const note=document.createElement('p');note.className='review-image-note';note.textContent=p.image_review.visually_reviewed?'Photo sample visually checked; open item for scope.':'Source / series photo · blind-box design may vary';body.append(note)}
 }
}
function productFromDialog(root){const title=root.querySelector('#detailTitle')?.textContent;if(!title)return;const label=root.querySelector('.brand-line')?.textContent;return data.products.find(p=>p.name===title&&p.brand===label)||data.products.find(p=>p.name===title)}
function enhanceDetail(){
 const root=document.getElementById('productDetail');if(!root||root.querySelector('.review-details'))return;
 const p=productFromDialog(root);if(!p)return;
 const d=p.details||{},review=p.image_review||{};const wrap=document.createElement('section');wrap.className='review-details';
 const fields=[['Material',d.material||p.material],['Dimensions',d.size],['Age stated by source',d.age],['Scale',d.scale],['Regular designs',p.regular_designs],['Secret designs',p.secret_designs],['Secret probability',p.secret_odds]];
 const facts=fields.filter(([,v])=>v!=null&&v!=='');
 const missing=[];if(!p.china_price)missing.push('Mainland price');if((p.launch||p.launch_estimate||{}).market!=='Mainland China')missing.push('Mainland launch');if(!p.sales)missing.push('Verified units sold');
 wrap.innerHTML=`<h3>Product specifications</h3>${facts.length?`<dl>${facts.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`:'<p class="review-small">These specifications were not supplied by the sources checked. They have not been guessed.</p>'}${d.source?`<p class="review-small">${a(d.source,'Specification source')} · Checked ${esc(d.checked)}</p>`:''}${p.official_product_url?`<p>${a(p.official_product_url,'Official product page')}</p>`:''}${d.features?.length?'<ul class="review-feature-list">'+d.features.map(f=>'<li>'+esc(f)+'</li>').join('')+'</ul>':''}${p.china_price?`<p class="review-small"><strong>China price basis:</strong> ${esc(p.china_price.basis)}${p.china_price.set_price?' · Full-box launch price '+currency(p.china_price.set_price,'CNY'):''}.</p>`:''}${missing.length?`<p class="review-small"><strong>Still to verify:</strong> ${esc(missing.join(' · '))}.</p>`:''}<h3>Photo source & matching</h3><p class="review-small">${esc(review.status||'Source photo recorded')}<br>${esc(review.scope||'Product or series photograph; exact random design can differ.')}<br>${esc(review.level||'Not individually visually audited.')} ${review.source?a(review.source,'Original photo listing'):''}</p><div class="review-photos">${[...new Set([p.image,...(p.gallery||[])])].slice(0,7).map((u,i)=>`<button class="review-photo" data-review-photo="${esc(safe(u))}" aria-label="Show source photo ${i+1}"><img src="${esc(safe(u))}" alt="Source image ${i+1} for ${esc(p.name)}" loading="lazy"></button>`).join('')}</div>${p.listings.filter(l=>l.options?.length).map(l=>`<details class="review-options"><summary>${esc(l.source)} — ${l.options.length} listed options & prices</summary><p class="review-small">${esc(l.market)} · Checked ${esc(l.options_checked)}. Individual characters, single blind boxes and full sets are different offers.</p><table><thead><tr><th>Option / pack</th><th>Listed price</th><th>Stock when checked</th></tr></thead><tbody>${l.options.map(v=>`<tr><td>${esc(v.name||'Unspecified')}${v.sku?'<br><small>'+esc(v.sku)+'</small>':''}</td><td>${esc(currency(v.price,v.currency))}</td><td>${typeof v.available==='boolean'?(v.available?'Available':'Unavailable'):'Not stated'}</td></tr>`).join('')}</tbody></table>${a(l.url,'Open this shop listing')}</details>`).join('')}`;
 const parent=root.querySelector('.detail-content');if(!parent)return;
 const anchor=[...parent.querySelectorAll('h3')].find(x=>/listings|prices|shop offers/i.test(x.textContent));if(anchor)anchor.before(wrap);else parent.append(wrap);
 const ipcontext=(data.brand_context||[]).filter(c=>p.brand===c.brand&&p.name.toLowerCase().includes(c.ip.toLowerCase()));
 for(const c of ipcontext){const x=document.createElement('div');x.className='review-context';x.innerHTML=`<strong>${esc(c.title)}</strong><p>${esc(c.summary)}</p>${a(c.source,'Company statement')} · ${esc(c.published)}<br>${esc(c.scope)}`;wrap.append(x)}
}
let pending=false;
function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;enhanceCards();enhanceDetail()})}
new MutationObserver(schedule).observe(document.getElementById('catalogGrid'),{childList:true});
new MutationObserver(schedule).observe(document.getElementById('productDetail'),{childList:true});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-review-brand],[data-review-photo]');if(!b)return;
 if(b.dataset.reviewPhoto){const main=document.querySelector('#productDetail .detail-photo img');if(main)main.src=b.dataset.reviewPhoto;return}
 const name=b.dataset.reviewBrand;const select=document.getElementById('brandSelect');if(select&&[...select.options].some(o=>o.value===name)){document.querySelector('.view-tab[data-view="catalog"]')?.click();select.value=name;select.dispatchEvent(new Event('change'));document.getElementById('results')?.scrollIntoView({block:'start'})}
});
brandPanel();enhanceCards();enhanceDetail();
})();

/* ATLAS_PLAIN_EVIDENCE */
(() => {
'use strict';
const d=window.TOY_ATLAS;if(!d)return;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=(u,t)=>{try{const url=new URL(u);return /^https?:$/.test(url.protocol)?`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`:''}catch{return ''}};
const sty=document.createElement('style');sty.textContent='.review-appeal{font-size:12px;line-height:1.6;border-top:1px solid #d1e1d6;margin-top:9px;padding-top:8px}.review-appeal strong{font-size:12px}.review-field-source{font-size:11px;display:block;margin-top:3px}.photo-scope-note{font-size:11px;line-height:1.6;color:#5a655e;margin:8px 0}@media(max-width:480px){.product-grid{grid-template-columns:minmax(0,1fr)!important}.product-card .photo-button{aspect-ratio:4/3}.product-card .photo-button img{height:100%;object-fit:contain}.review-reason,.review-spec{font-size:13px}.review-reason small{font-size:12px}.product-card .price-caption{font-size:12px}}';document.head.append(sty);
function decorate(){
 for(const card of document.querySelectorAll('.product-card[data-product-id]')){
  if(card.dataset.plainEvidence)continue;const p=d.products.find(p=>p.id===card.dataset.productId);if(!p)continue;
  const reason=card.querySelector('.review-reason');if(reason&&p.trend?.possible_appeal&&!reason.querySelector('.review-appeal')){const x=document.createElement('div');x.className='review-appeal';x.innerHTML='<strong>Possible appeal — interpretation</strong>'+esc(p.trend.possible_appeal);reason.append(x)}
  if(card.querySelector('.review-spec')||reason)card.dataset.plainEvidence='1';
 }
 const root=document.getElementById('productDetail');if(!root||!root.querySelector('.review-details'))return;
 const title=root.querySelector('#detailTitle')?.textContent;const p=d.products.find(p=>p.name===title);if(!p)return;
 const panel=root.querySelector('.review-details');if(panel.dataset.plainEvidence)return;panel.dataset.plainEvidence='1';
 const mapping={'Material':'material','Dimensions':'size','Age stated by source':'age','Scale':'scale'};
 for(const dt of panel.querySelectorAll('dl dt')){const field=mapping[dt.textContent],e=p.details?.field_sources?.[field];if(e){const small=document.createElement('small');small.className='review-field-source';small.innerHTML=source(e.url,'Field source');dt.nextElementSibling?.append(small)}}
 if(p.image_gallery_note){const note=document.createElement('p');note.className='photo-scope-note';note.textContent=p.image_gallery_note;panel.querySelector('.review-photos')?.before(note)}
 if(p.trend?.possible_appeal){const x=document.createElement('section');x.className='review-context';x.innerHTML='<strong>Possible appeal — interpretation, not proven sales causation</strong><p>'+esc(p.trend.possible_appeal)+'</p>';panel.append(x)}
}
let queued=false;const queue=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;decorate()})};
for(const id of ['catalogGrid','productDetail']){const root=document.getElementById(id);if(root)new MutationObserver(queue).observe(root,{childList:true,subtree:true})}
decorate();
})();
